use xiom.io;

type Queue = {
  items: Vec[Int];
  capacity: Int;
  invariant: items.len() <= capacity;
}

fn enqueue(q: &mut Queue, item: Int)
  requires: q.items.len() < q.capacity;
  ensures: q.items.len() == q@pre.items.len() + 1;
{
  q.items.push(item);
}

fn dequeue(q: &mut Queue) -> Option[Int]
  requires: q.items.len() > 0;
  ensures: q.items.len() == q@pre.items.len() - 1;
{
  let first = q.items[0];
  q.items.remove(0);
  return Some(first);
}

fn is_full(q: &Queue) -> Bool {
  return q.items.len() == q.capacity;
}

fn main() -> Int {
  var q: Queue = Queue{ items: Vec::new(), capacity: 5 };
  enqueue(&mut q, 10);
  enqueue(&mut q, 20);
  enqueue(&mut q, 30);
  io.println("Is full: " + is_full(&q).to_str());
  dequeue(&mut q);
  dequeue(&mut q);
  dequeue(&mut q);
  return q.items.len();
}
